// ---------------------------------------------------------------------------
// Strategy: flock_race (parallel fan-out, first valid wins; legacy "ast_race" still accepted)
// ---------------------------------------------------------------------------
func (r *Router) routeAstRace(w http.ResponseWriter, req *http.Request, rt *routingContext) {
	providers := r.registry.ForModel(rt.modelID)
	ctx, cancel := context.WithTimeout(req.Context(), time.Duration(r.cfg.RequestTimeout)*time.Second)
	defer cancel()

	type result struct {
		resp *http.Response
		p    Provider
		err  error
	}
	results := make(chan result, len(providers))

	for _, p := range providers {
		go func(p Provider) {
			resp, err := r.call(ctx, p, req, rt)
			results <- result{resp, p, err}
		}(p)
	}

	var lastErr error
	for i := 0; i < len(providers); i++ {
		select {
		case res := <-results:
			if res.err == nil && res.resp != nil && res.resp.StatusCode < 500 {
				r.getCircuit(res.p.ID).RecordSuccess()
				r.stream(w, res.resp, rt)
				return
			}
			if res.resp != nil {
				res.resp.Body.Close()
			}
			lastErr = res.err
		case <-ctx.Done():
			shared.SendError(w, req, fmt.Errorf("flock_race timeout"))
			return
		}
	}
	shared.SendError(w, req, fmt.Errorf("flock_race all failed: %w", lastErr))
}

