	"github.com/mostlygeek/llama-swap/internal/logmon"
	"github.com/mostlygeek/llama-swap/internal/shared"
)

// Router implements router.Router for cloud provider dispatch.
type Router struct {
	cfg       *FlockConfig
	logger    *logmon.Monitor
	registry  *ProviderRegistry
	healthDB  *HealthDB
	limiter   *RateLimiter
	circuits  sync.Map // string -> *CircuitBreaker
	coalescer *RequestCoalescer
	metrics   *MetricsCollector
	client    *http.Client
	rrCounter uint64
}

// routingContext holds per-request mutable state.
type routingContext struct {
	modelID   string
	isAST     bool
	bodyBytes []byte
	bodyJSON  map[string]interface{}
	startTime time.Time
	strategy  string
}

// NewRouter creates a flock Router from config.
func NewRouter(cfg *FlockConfig, logger *logmon.Monitor) (*Router, error) {
	if cfg == nil {
		cfg = &FlockConfig{}
	}
	cfg.Defaults()

	reg := NewProviderRegistry(cfg.Providers)
	health := NewHealthDB(cfg.DbPath)
	limiter := NewRateLimiter(cfg.Providers)

	r := &Router{
		cfg:       cfg,
		logger:    logger,
		registry:  reg,
		healthDB:  health,
		limiter:   limiter,
		coalescer: NewRequestCoalescer(5 * time.Second),
		metrics:   NewMetricsCollector(),
		client: &http.Client{
			Timeout: time.Duration(cfg.RequestTimeout) * time.Second,
			Transport: &http.Transport{
				MaxIdleConns:        100,
				MaxIdleConnsPerHost: 10,
				IdleConnTimeout:     90 * time.Second,
				DisableCompression:  true,
			},
		},
	}
	go r.healthProbeLoop()
	return r, nil
}

// Handles returns true if any provider can serve modelID.
func (r *Router) Handles(modelID string) bool {
	if modelID == "" {
		return false
	}
	for _, p := range r.registry.All() {
		for _, m := range p.Models {
