        _ => "other".to_owned(),
    }
}

/// Statuses worth waiting out: rate limit and transient server-side trouble.
fn retryable(status: reqwest::StatusCode) -> bool {
    matches!(status.as_u16(), 429 | 500 | 502 | 503 | 504)
